<?php /** @var array $bars, $products, $stock, $moves, $sold; string $btab, $bbase */ echo view('pro/bars/_nav', compact('btab', 'bbase'));
$tracked = array_filter($products, fn($p) => (int)$p['track_stock']); ?>
<p class="muted lead-sm">Le stock baisse à chaque vente et remonte si la vente est annulée. Saisis les livraisons, les transferts entre la réserve et les bars, et l'inventaire de fin : l'écart est enregistré.</p>
<div class="card table-card"><div class="card-head"><h2>Stock par bar</h2><a class="btn btn-sm btn-light" href="<?= url($bbase . '/stocks', ['export' => 'csv']) ?>">CSV</a></div>
  <div class="table-wrap"><table class="table"><thead><tr><th>Produit</th><?php foreach ($bars as $b): ?><th class="num"><?= e($b['name']) ?></th><?php endforeach; ?><th class="num">Total</th></tr></thead><tbody>
    <?php foreach ($tracked as $p): $sum = 0; ?><tr><td><b><?= e($p['name']) ?></b></td><?php foreach ($bars as $b): $q = $stock[(int)$p['id']][(int)$b['id']] ?? 0; $sum += $q; $al = $p['stock_alert'] !== null ? (int)$p['stock_alert'] : 10; ?>
      <td class="num"><span class="<?= $q <= 0 ? 'text-red' : ($q <= $al ? 'text-orange' : '') ?>"><b><?= $q ?></b></span><br><small class="muted"><?= (int)($sold[(int)$p['id']][(int)$b['id']] ?? 0) ?> vendus</small></td><?php endforeach; ?><td class="num"><b><?= $sum ?></b></td></tr><?php endforeach; ?>
    <?php if (!$tracked): ?><tr><td colspan="<?= count($bars) + 2 ?>" class="empty">Aucun produit suivi : coche « Suivre le stock » dans le catalogue, ou fais une première entrée ci-dessous.</td></tr><?php endif; ?>
  </tbody></table></div></div>
<div class="split-3 mt">
  <?php $pSel = '<select name="product_id" required>' . implode('', array_map(fn($p) => '<option value="' . (int)$p['id'] . '">' . e($p['name']) . '</option>', $products)) . '</select>'; $bSel = fn($n) => '<select name="' . $n . '">' . implode('', array_map(fn($b) => '<option value="' . (int)$b['id'] . '">' . e($b['name']) . '</option>', $bars)) . '</select>'; ?>
  <form method="post" class="card stack"><?= csrf_field() ?><input type="hidden" name="action" value="in"><h2>Entrée</h2><small class="muted">Livraison, réassort. Négatif pour une casse.</small><?= $pSel ?><?= $bSel('bar_id') ?><input name="qty" inputmode="numeric" placeholder="Quantité" required><input name="note" placeholder="Note (facultatif)"><button class="btn btn-sm">Enregistrer</button></form>
  <form method="post" class="card stack"><?= csrf_field() ?><input type="hidden" name="action" value="transfer"><h2>Transfert</h2><small class="muted">D'un bar (ou de la réserve) vers un autre.</small><?= $pSel ?><label class="muted">De</label><?= $bSel('bar_id') ?><label class="muted">Vers</label><?= $bSel('to_bar_id') ?><input name="qty" inputmode="numeric" placeholder="Quantité" required><button class="btn btn-sm">Transférer</button></form>
  <form method="post" class="card stack"><?= csrf_field() ?><input type="hidden" name="action" value="count"><h2>Inventaire</h2><small class="muted">Quantité réellement comptée.</small><?= $pSel ?><?= $bSel('bar_id') ?><input name="qty" inputmode="numeric" placeholder="Comptés" required><button class="btn btn-sm">Enregistrer</button></form>
</div>
<div class="card mt"><h2>Derniers mouvements</h2>
  <?php foreach ($moves as $m): ?><div class="list-item"><span class="grow"><b><?= e($m['product']) ?></b> · <?= e($m['bar']) ?><br><small class="muted"><?= e(['in' => 'Entrée', 'transfer' => 'Transfert', 'inventory' => 'Inventaire', 'undo' => 'Annulation de vente', 'loss' => 'Perte', 'refund' => 'Remboursement de ticket'][$m['kind']] ?? $m['kind']) ?><?= $m['note'] ? ' · ' . e($m['note']) : '' ?> · <?= e(date('d/m H:i', strtotime($m['created_at']))) ?> <?= e((string)$m['who']) ?></small></span><b class="<?= (int)$m['delta'] < 0 ? 'text-red' : 'text-green' ?>"><?= (int)$m['delta'] > 0 ? '+' : '' ?><?= (int)$m['delta'] ?></b></div><?php endforeach; ?>
  <?php if (!$moves): ?><p class="muted mb0">Aucun mouvement.</p><?php endif; ?></div>
